; Historical MCP JVM probe source. Load test dependencies in a scoped
; DynamicClassLoader as described in the landing note before evaluating it.
; The canonical regression is maintained in test/seon/datahike_fork_test.clj.
(def probe-source
  "(defn turn-cache-probe [label test-symbols]\n (let [thread (Thread/currentThread) entering (.getContextClassLoader thread)\n       connection (seon.operator/connection \"default\")]\n  (try\n   (.setContextClassLoader thread turn-cache-loader)\n   (with-bindings {clojure.lang.Compiler/LOADER turn-cache-loader}\n    (seon.schema/call-with-projection\n     (seon.db/carried-projection (seon.db/db connection))\n     (fn []\n      (let [manifest (seon.fn/build-manifest {:seon.fn/roots [\"src\" \"test\"]})\n            base (with-redefs-fn {#'seon.test-support/source-manifest (delay manifest)}\n                   #(#'seon.test-support/create-base nil))]\n       (try\n        (with-redefs-fn {(ns-resolve 'seon.test-support 'database-base) (delay base)}\n         (fn []\n          (mapv (fn [test-symbol]\n                  (let [result (seon.test/run (requiring-resolve test-symbol) connection\n                                {:seon.test/remaining-ms 120000\n                                 :seon.test.run/provenance\n                                 (seon.test.runner/provenance (seon.db/db connection))})]\n                   (spit (str \"tmp/turn-test-cache/\" label \"-\" (name test-symbol) \".edn\") (pr-str result))\n                   (select-keys result [:seon.test/sym :seon.test/pass-count :seon.test/fail-count\n                                        :seon.test/error-count :seon.test/run])))\n                test-symbols)))\n        (finally (#'seon.test-support/close-base! base)))))))\n   (finally (.setContextClassLoader thread entering)))))")
